WITH combined_sales AS ( SELECT cs.cs_promo_sk AS promo_sk, cs.cs_net_profit AS net_profit, cs.cs_ext_discount_amt AS discount_amt, cs.cs_sold_date_sk AS sold_date_sk, 'catalog' AS channel, CAST(NULL AS integer) AS web_site_sk FROM catalog_sales cs UNION ALL SELECT ws.ws_promo_sk, ws.ws_net_profit, ws.ws_ext_discount_amt, ws.ws_sold_date_sk, 'web' AS channel, ws.ws_web_site_sk FROM web_sales ws ), promo_agg AS ( SELECT cs.promo_sk, cs.channel, COALESCE(MAX(cs.web_site_sk), -1) AS web_site_sk, SUM(cs.net_profit) AS total_net_profit, SUM(cs.discount_amt) AS total_discount_amt, SUM(cs.net_profit) - SUM(cs.discount_amt) AS profit_minus_discount FROM combined_sales cs GROUP BY cs.promo_sk, cs.channel ) SELECT pa.promo_sk, pa.channel, pa.total_net_profit, pa.total_discount_amt, pa.profit_minus_discount, DENSE_RANK() OVER (PARTITION BY pa.channel ORDER BY pa.profit_minus_discount DESC) AS profit_minus_discount_rank FROM promo_agg pa WHERE pa.profit_minus_discount > 0 ORDER BY pa.channel, profit_minus_discount_rank LIMIT 20
